#!/usr/bin/env bash
# Local single-GPU runner generated by the run-experiment skill.
# Project: DataCook
# Created: 2026-07-22
# Commit:  1566c03404
#
# Run inside screen: bash jobs/datacook-3d-four-local.sh [GPU_ID]

set -euo pipefail

JOB_NAME="datacook-3d-four"
LOG_DIR="outputs/logs/${JOB_NAME}"
OUTPUT_DIR="results/revision_pipeline_3d"
GPU_ID="${1:-0}"
GIT_COMMIT="1566c03404"

mkdir -p "$LOG_DIR" "$OUTPUT_DIR"
LOG_FILE="$LOG_DIR/${JOB_NAME}-$(date +%Y%m%d-%H%M%S).log"

if command -v conda >/dev/null 2>&1; then
  source "$(conda info --base)/etc/profile.d/conda.sh"
  conda activate datacook
fi

cd "$(dirname "$0")/.."
export CUDA_VISIBLE_DEVICES="$GPU_ID"
export CUBLAS_WORKSPACE_CONFIG=:4096:8

echo "=========================================" | tee "$LOG_FILE"
echo "Job:    $JOB_NAME" | tee -a "$LOG_FILE"
echo "Start:  $(date)" | tee -a "$LOG_FILE"
echo "Commit: $GIT_COMMIT" | tee -a "$LOG_FILE"
echo "GPU:    $GPU_ID" | tee -a "$LOG_FILE"
echo "Log:    $LOG_FILE" | tee -a "$LOG_FILE"
echo "=========================================" | tee -a "$LOG_FILE"

set +e
python -u run_datacook_suite.py \
  --config configs/pipelines/medmnist3d_four.yaml 2>&1 | tee -a "$LOG_FILE"
EXIT_CODE=${PIPESTATUS[0]}
set -e

echo "=========================================" | tee -a "$LOG_FILE"
echo "End:  $(date)" | tee -a "$LOG_FILE"
echo "Exit: $EXIT_CODE" | tee -a "$LOG_FILE"
echo "=========================================" | tee -a "$LOG_FILE"
exit "$EXIT_CODE"
